Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "USES_OBSERVATION_AS_INPUT",
    "definition": "The action takes an identifiable value or data payload supplied by the specified prior observation as an operational input.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action receiving the input."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The prior recorded tool result supplying the input value or data payload."
      }
    ],
    "assertion_conditions": [
      "The observation precedes the action in the recorded trajectory.",
      "An argument, command operand, file content, or data payload of the action is traceable to a value reported by the observation, such as a commit identifier or recovered string.",
      "The traced value is used by the action as an input rather than being merely mentioned in the action's rationale."
    ],
    "exclusion_conditions": [
      "Using an observation only to choose which action to take, without supplying an argument or payload value, does not satisfy this predicate.",
      "Temporal adjacency, shared topic, or a general reference to the same repository without a traceable input value does not satisfy this predicate."
    ]
  },
  {
    "name": "GUIDES_ACTION_CHOICE",
    "definition": "The specified observation provides the explicit informational or diagnostic basis for selecting the specified later action.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The prior recorded tool result whose finding motivates the action selection."
      },
      {
        "name": "action",
        "type": "action",
        "description": "The later action chosen in response to that finding."
      }
    ],
    "assertion_conditions": [
      "The observation precedes the action.",
      "The action targets, inspects, or responds to a specific item revealed by the observation, such as a commit identifier, object, or presence/absence result.",
      "The recorded reasoning or the action's immediate context identifies that observation as the basis for choosing the action, rather than the action merely using the observation as an input value."
    ],
    "exclusion_conditions": [
      "An observation that supplies an argument value without evidence that it was the basis for choosing the action does not satisfy this predicate.",
      "Actions that are merely adjacent in time or share a repository scope without an explicit decision link do not satisfy this predicate."
    ]
  },
  {
    "name": "USES_REASONING_AS_CRITERION",
    "definition": "The action uses a criterion, check, or evaluation condition stated in the specified prior reasoning node to structure or evaluate its operation.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action applying the criterion."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The prior reasoning node that states the criterion or check condition."
      }
    ],
    "assertion_conditions": [
      "The reasoning node precedes the action.",
      "The reasoning node explicitly states one or more criteria, checks, or conditions to be applied, such as verifying absence of a pattern, preserving specified files, or comparing object sets.",
      "The action's command, arguments, or selected checks implement those stated criteria."
    ],
    "exclusion_conditions": [
      "A reasoning node that only states a general goal, background fact, or plan step without a criterion or evaluation condition does not satisfy this predicate.",
      "An action that happens to match a later description without the criterion being stated beforehand does not satisfy this predicate."
    ]
  },
  {
    "name": "IMPLEMENTS_PLAN",
    "definition": "The action executes one or more steps of an explicit plan stated in the specified prior reasoning node.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action carrying out a planned step."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The prior reasoning node containing the explicit plan."
      }
    ],
    "assertion_conditions": [
      "The reasoning node precedes the action.",
      "The reasoning node enumerates intended future operations or checks.",
      "The action performs an operation corresponding to one or more enumerated steps, such as writing a planned file or running planned cleanup or verification commands."
    ],
    "exclusion_conditions": [
      "An action that is merely consistent with a general goal, or with a single unenumerated intention, does not satisfy this predicate.",
      "A retrospective summary of actions already taken does not supply the plan for this predicate."
    ]
  },
  {
    "name": "ATTEMPTS_REPAIR",
    "definition": "The action performs an intervention intended to remove or neutralize an unwanted condition reported by the specified prior observation.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The repair or cleanup action."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The prior observation reporting the unwanted condition, defect, or exposure."
      }
    ],
    "assertion_conditions": [
      "The failure observation precedes the repair action.",
      "The failure observation identifies an unwanted condition, such as exposed content or a retained object.",
      "The action's command or operation targets the reported condition or the mechanism retaining it, for example by expiring reflogs and pruning unreachable objects.",
      "The recorded reasoning or plan supports that the action is intended as remediation rather than merely inspection."
    ],
    "exclusion_conditions": [
      "An action that only inspects, confirms, or reports the unwanted condition does not satisfy this predicate.",
      "A general cleanup operation without a link to the reported condition does not satisfy this predicate."
    ]
  },
  {
    "name": "CONFIRMS_REPAIR",
    "definition": "The check observation reports that the unwanted condition addressed by the repair action and reported in the failure observation is no longer present, or otherwise confirms that the repair succeeded.",
    "parameters": [
      {
        "name": "repair",
        "type": "action",
        "description": "The action intended to repair or remove the reported condition."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The observation reporting the condition before the repair."
      },
      {
        "name": "check",
        "type": "observation",
        "description": "The later observation produced by a verification action that assesses the repair."
      }
    ],
    "assertion_conditions": [
      "The failure observation precedes the repair action, and the repair action precedes the check observation.",
      "The check observation reports absence, not-found, clean, or otherwise successful status for the same condition addressed by the repair.",
      "The repair action, failure observation, and check observation concern the same subject or repository state."
    ],
    "exclusion_conditions": [
      "A check observation that still reports the condition, or reports an unrelated condition, does not satisfy this predicate.",
      "Running a verification command alone does not confirm repair unless the returned observation indicates success."
    ]
  },
  {
    "name": "IS_PLAN",
    "definition": "The reasoning node contains an explicit, ordered or enumerated plan of future actions rather than only a conclusion, description, or single intention.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node being assessed as a plan."
      }
    ],
    "assertion_conditions": [
      "The text enumerates two or more intended future operations or checks, often with ordinal markers or bullets.",
      "The enumerated items specify actions or evaluation steps to be carried out later."
    ],
    "exclusion_conditions": [
      "A single statement of intent, a task restatement, or a retrospective summary of completed work does not satisfy this predicate.",
      "A list of observations or facts without future operations does not satisfy this predicate."
    ]
  },
  {
    "name": "DERIVES_CONCLUSION",
    "definition": "The conclusion reasoning node states a conclusion that is explicitly supported by the specified prior observations.",
    "parameters": [
      {
        "name": "inputs",
        "type": "observation[]",
        "description": "The prior observations supplying evidence for the conclusion."
      },
      {
        "name": "conclusion",
        "type": "reasoning",
        "description": "The reasoning node stating the conclusion drawn from those observations."
      }
    ],
    "assertion_conditions": [
      "Every observation in inputs precedes the conclusion in the recorded trajectory.",
      "The conclusion text cites, summarizes, or reasons from findings in those observations, such as verification checks passing, an object being absent, or a task objective being met.",
      "The conclusion is asserted as a finding or result, not merely as a plan for future action."
    ],
    "exclusion_conditions": [
      "A reasoning node that only lists future steps or restates raw observations without drawing a conclusion does not satisfy this predicate.",
      "A conclusion not traceable to the specified observations does not satisfy this predicate."
    ]
  },
  {
    "name": "IS_FINAL_TASK_SUMMARY",
    "definition": "The reasoning node is a final response that explicitly declares the task complete and summarizes the actions and results that fulfilled the task.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node containing the final task summary."
      }
    ],
    "assertion_conditions": [
      "The text explicitly states that the task is complete or that all objectives have been addressed.",
      "The text summarizes the completed actions and/or verified results, often with numbered or bulleted objectives.",
      "The summary occurs after execution of the task's main actions."
    ],
    "exclusion_conditions": [
      "An intermediate progress note, a plan for future work, or a conclusion without a completion declaration does not satisfy this predicate.",
      "A simple final status word without a summary does not satisfy this predicate."
    ]
  }
]

